import pandas as pd
import glob
import os

# Find all CSV files generated by btc_trends.py
trend_files = glob.glob("bitcoin_trends_*.csv")

# List to hold dataframes
dfs = []

# Read each file and append to list
for file in sorted(trend_files):  # Sort by filename to maintain chronological order
    df = pd.read_csv(file, parse_dates=['date'])
    dfs.append(df)

# Concatenate all dataframes
merged_df = pd.concat(dfs, ignore_index=True)

# Drop the 'isPartial' column if it exists
if 'isPartial' in merged_df.columns:
    merged_df.drop('isPartial', axis=1, inplace=True)

# Sort by date to ensure order
merged_df.sort_values('date', inplace=True)

# Drop any duplicates, just in case of overlaps
merged_df.drop_duplicates(subset='date', inplace=True)

# Save to a single CSV
output_file = "merged_bitcoin_trends.csv"
merged_df.to_csv(output_file, index=False)

print(f"Merged data saved to {output_file}")
print(merged_df.head())